flow.typescript:
// D29 · Part 0~5 · 오늘의 흐름 전체: 출입증 → 방 입장 → 비서 출근 → 세션 한 턴 → 음성 트랙 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_flow.ts
//   사용자 토큰을 확인하고 방에 들이면, 서버가 비서 일감을 만들어 세션 한 턴을 돌리고 답을 음성 트랙으로 publish
//   (대체: 실제 LiveKit 대신 이 파일 안의 모의 방·서명·가짜 LLM)
import { createHmac } from "node:crypto";

const SECRET = "dev-secret-do-not-use-in-prod"; // 개발용 가짜 키

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const token = (identity: string, room: string): string => `${identity}|${room}|` + createHmac("sha256", SECRET).update(`${identity}|${room}`).digest("hex").slice(0, 16);

function valid(tok: string): boolean {
  const [identity, room] = tok.split("|");
  return tok === token(identity, room);
}

interface Room {
  name: string;
  events: string[];
}

async function agentEntrypoint(room: Room, userText: string): Promise<void> {
  // 비서 일감: 방에 연결 → 사용자 말을 LLM(가짜)에 → 답을 음성 트랙으로 publish
  room.events.push("agent: connect");
  const reply = userText.includes("예약") ? "네, 예약 도와드릴게요." : "다시 말씀해 주세요.";
  room.events.push(`agent: publish voice '${reply}'`);
}

const room: Room = { name: "clinic-1", events: [] };
const userTok = token("user-1", "clinic-1");
if (valid(userTok)) {
  room.events.push("user-1: join (토큰 확인 통과)");
  await agentEntrypoint(room, "내일 예약하고 싶어요"); // 서버가 방이 생긴 걸 보고 비서를 보냄
}
const forged = userTok.replace("user-1", "admin");
for (const e of room.events) console.log(" ", e);
check(room.events[0].startsWith("user-1") && room.events[1] === "agent: connect" && room.events[2].includes("예약 도와드릴게요") && !valid(forged), "토큰 확인 → 비서 연결 → 답 publish 순서여야 하고, 위조 토큰은 거절돼야 해요.");

room.typescript:
// D29 · Part 1 · 방 · 참가자 · 트랙: 누가 무엇을 내고 누가 받나 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_room.ts   (LiveKit 서버 없이 같은 파일 안의 모의 Room)
//   사용자가 마이크 트랙을 publish하면 같은 방의 비서가 subscribe하고, 비서의 음성 트랙은 사용자가 받는다
//   (대체: livekit-client의 Room 대신 이벤트 목록을 남기는 미니 Room)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Participant {
  identity: string;
  kind: string; // STANDARD(사람) · AGENT(비서)
  published: string[];
  subscribed: string[];
}

class Room {
  name: string;
  people = new Map<string, Participant>();
  events: string[] = [];
  constructor(name: string) {
    this.name = name;
  }
  connect(identity: string, kind: string): Participant {
    const p: Participant = { identity, kind, published: [], subscribed: [] };
    for (const other of this.people.values()) for (const t of other.published) this.subscribe(p, other, t); // 먼저 와 있던 사람의 트랙은 입장하자마자 받는다
    this.people.set(identity, p);
    this.events.push(`participant_connected ${identity}`);
    return p;
  }
  publish(p: Participant, track: string): void {
    p.published.push(track);
    this.events.push(`track_published ${p.identity}/${track}`);
    for (const other of this.people.values()) if (other !== p) this.subscribe(other, p, track); // 이미 방에 있는 다른 참가자가 자동 구독
  }
  subscribe(who: Participant, owner: Participant, track: string): void {
    who.subscribed.push(`${owner.identity}/${track}`);
    this.events.push(`track_subscribed ${who.identity} <- ${owner.identity}/${track}`);
  }
}

const room = new Room("clinic-1");
const user = room.connect("user-1", "STANDARD");
room.publish(user, "mic"); // 사용자가 마이크 트랙을 낸다
const agent = room.connect("hana-agent", "AGENT"); // 비서가 늦게 입장해도 mic를 받는다
room.publish(agent, "voice"); // 비서가 음성 트랙을 낸다
for (const e of room.events) console.log(" ", e);
check(agent.subscribed.join() === "user-1/mic" && user.subscribed.join() === "hana-agent/voice" && room.events[0] === "participant_connected user-1", "비서는 user-1/mic를, 사용자는 hana-agent/voice를 구독해야 해요.");

token.typescript:
// D29 · Part 1 · 토큰의 세 조각: 출입증(Access Token) 만들고 · 열어 보고 · 위조 확인 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_token.ts   (LiveKit 서버·SDK 없이 JWT HS256을 직접 구현)
//   헤더 · 내용(누가·어느 방·무슨 권한) · 서명 세 조각. 내용은 누구나 읽지만 서명 키(API secret)가 없으면 고칠 수 없다
//   (대체: livekit-server-sdk의 AccessToken 대신 같은 구조를 createHmac으로 직접 만든 것 · 키는 개발용 가짜 값)
import { createHmac, timingSafeEqual } from "node:crypto";

const API_KEY = "devkey";
const API_SECRET = "dev-secret-do-not-use-in-prod"; // 개발용 가짜 키 (실제 키는 서버 환경 변수에만)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Claims {
  iss: string;
  sub: string;
  exp: number;
  video: Record<string, string | boolean>;
}

const b64 = (s: string): string => Buffer.from(s).toString("base64url");
const sign = (head: string, body: string): string => createHmac("sha256", API_SECRET).update(`${head}.${body}`).digest("base64url");

function makeToken(identity: string, room: string, now: number, ttl: number = 600, agent: boolean = false): string {
  // 출입증 발급: 사용자는 말하고 듣기만, 비서(agent)는 방 관리 권한도 가진다
  const grant: Record<string, string | boolean> = { room, roomJoin: true, canPublish: true, canSubscribe: true };
  if (agent) grant.roomAdmin = true;
  const claims: Claims = { iss: API_KEY, sub: identity, exp: now + ttl, video: grant };
  const head = b64(JSON.stringify({ alg: "HS256", typ: "JWT" }));
  const body = b64(JSON.stringify(claims));
  return `${head}.${body}.${sign(head, body)}`;
}

function verify(token: string, now: number): { ok: boolean; claims: Claims } {
  // 서명이 맞고 기한이 안 지났는지 확인. 내용은 서명과 상관없이 읽을 수 있다
  const [head, body, sig] = token.split(".");
  const want = Buffer.from(sign(head, body));
  const got = Buffer.from(sig);
  const good = want.length === got.length && timingSafeEqual(want, got);
  const claims: Claims = JSON.parse(Buffer.from(body, "base64url").toString());
  return { ok: good && claims.exp > now, claims };
}

const NOW = 1_700_000_000;
const user = makeToken("user-1", "clinic-1", NOW);
const agent = makeToken("hana-agent", "clinic-1", NOW, 600, true);
const u = verify(user, NOW);
const a = verify(agent, NOW);
const [head, , sig] = user.split(".");
const forged = `${head}.${b64(JSON.stringify({ ...u.claims, sub: "admin" }))}.${sig}`; // 내용만 바꾸고 서명은 그대로
const f = verify(forged, NOW);
const late = verify(user, NOW + 601);
console.log("사용자 권한:", JSON.stringify(u.claims.video), "\n비서 권한  :", JSON.stringify(a.claims.video));
console.log(`정상 ${u.ok} · 위조 ${f.ok} · 기한 지남 ${late.ok}`);
check(u.ok && a.ok && !f.ok && !late.ok && !("roomAdmin" in u.claims.video) && a.claims.video.roomAdmin === true, "위조·만료 토큰은 거절하고, 비서만 roomAdmin을 가져야 해요.");

session.typescript:
// D29 · Part 2 · Agent와 Session: 대본(instructions)을 쓰고 글자로 먼저 한 턴 돌려 보기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_session.ts
//   Agent = 성격과 대본, AgentSession = 대화를 실제로 돌리는 엔진. session.run({ userInput })은 음성 없이 LLM만 시험한다
//   (대체: @livekit/agents의 Agent·AgentSession과 실제 LLM 대신, 규칙으로 답하는 가짜 LLM)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Message {
  role: string;
  content: string;
}

class Agent {
  instructions: string; // 시스템 프롬프트가 곧 비서의 성격
  constructor(instructions: string) {
    this.instructions = instructions;
  }
}

class Hana extends Agent {
  constructor() {
    super("당신은 한빛치과 예약 비서 하나입니다. 한 번에 한두 문장으로 짧게 답하세요.");
  }
}

class FakeLLM {
  async chat(_instructions: string, history: Message[]): Promise<string> {
    const last = history[history.length - 1].content;
    return last.includes("예약") ? "네, 예약 도와드릴게요. 언제가 좋으세요?" : "죄송해요, 잘 못 들었어요.";
  }
}

interface Event {
  type: string;
  role: string;
  text: string;
}

class AgentSession {
  llm: FakeLLM;
  agent: Agent | null = null;
  history: Message[] = [];
  constructor(llm: FakeLLM) {
    this.llm = llm;
  }
  async start(agent: Agent): Promise<void> {
    this.agent = agent;
  }
  async run(userInput: string): Promise<Event[]> {
    // 글자로 한 턴: 사용자 메시지 → LLM → 비서 메시지. 음성(STT·TTS·VAD)은 쓰지 않는다
    this.history.push({ role: "user", content: userInput });
    const reply = await this.llm.chat(this.agent?.instructions ?? "", this.history);
    this.history.push({ role: "assistant", content: reply });
    return [{ type: "message", role: "user", text: userInput }, { type: "message", role: "assistant", text: reply }];
  }
}

const session = new AgentSession(new FakeLLM());
await session.start(new Hana());
const events = await session.run("내일 예약하고 싶어요");
for (const e of events) console.log(`${e.role.padStart(9)}: ${e.text}`);
check(
  events.map((e) => `${e.type}/${e.role}`).join() === "message/user,message/assistant" && events[1].text.includes("예약") && session.history.length === 2 && (session.agent?.instructions ?? "").includes("한빛치과"),
  "사용자 메시지 다음에 비서 메시지가 와야 하고, 대본에 한빛치과가 있어야 해요.",
);

pipeline.typescript:
// D29 · Part 3 · 세션 안의 흐름: 마이크 → VAD → STT → 턴 판단 → LLM → TTS → 스피커 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_pipeline.ts
//   가짜 마이크가 말을 흘려 넣고 가짜 스피커가 소리를 받는다. 통화 기록에 단계별 시각을 남기고 e2e 지연 식을 확인
//   e2e_latency ≈ 턴 끝 판단 지연 + LLM 첫 글자 + TTS 첫 소리
//   (대체: 실제 마이크·스피커·서비스 대신 고정 지연 STT 0.3 · 턴 0.5 · LLM 0.4 · TTS 0.2초)
const STT_SEC = 0.3;
const TURN_SEC = 0.5;
const LLM_SEC = 0.4;
const TTS_SEC = 0.2;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function fakeCall(speechEnd: number): { log: [number, string][]; e2e: number } {
  // 사용자가 speechEnd초에 말을 마쳤을 때 단계별 (시각, 이벤트) 기록과 e2e 지연
  const turnEnd = speechEnd + Math.max(TURN_SEC, STT_SEC); // 조용함 판단과 글자 도착 중 늦은 쪽
  const firstSound = turnEnd + LLM_SEC + TTS_SEC;
  const log: [number, string][] = [
    [speechEnd, "mic: 사용자 말 끝"],
    [speechEnd + STT_SEC, "stt: 글자 도착"],
    [turnEnd, "turn: 사용자 턴 종료"],
    [turnEnd + LLM_SEC, "llm: 첫 글자"],
    [firstSound, "speaker: 첫 소리"],
  ];
  return { log, e2e: Math.round((firstSound - speechEnd) * 100) / 100 };
}

const { log, e2e } = fakeCall(5.0);
for (const [t, e] of log) console.log(`  ${t.toFixed(2).padStart(5)}초  ${e}`);
const turnDelay = log[2][0] - log[0][0];
check(log.map(([, e]) => e.split(":")[0]).join() === "mic,stt,turn,llm,speaker" && e2e === 1.1 && Math.round((turnDelay + LLM_SEC + TTS_SEC) * 100) / 100 === e2e, "e2e = 턴 끝 판단 0.5 + LLM 0.4 + TTS 0.2 = 1.1초예요.");

plugin.typescript:
// D29 · Part 3 · 플러그인의 콘센트: STT · TTS를 갈아 끼워도 세션 코드는 그대로 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_plugin.ts
//   STT·TTS는 정해진 모양(interface)만 지키면 어떤 회사 것이든 꽂힌다. 두 쌍을 번갈아 꽂아 같은 통화를 돌린다
//   (대체: Whisper·Edge TTS·클라우드 플러그인 대신 사전 표로 답하는 가짜 구현 두 쌍)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface STT {
  // 콘센트 모양 1: 오디오(여기선 꼬리표) → 글자
  name: string;
  recognize(audio: string): Promise<string>;
}

interface TTS {
  // 콘센트 모양 2: 글자 → 오디오(여기선 바이트 수)
  name: string;
  synthesize(text: string): Promise<number>;
}

const CLIPS: Record<string, string> = { clip1: "내일 예약하고 싶어요" };
const localWhisperSTT: STT = { name: "local-whisper", recognize: async (audio) => CLIPS[audio] };
const cloudSTT: STT = { name: "cloud-stt", recognize: async (audio) => CLIPS[audio].trim() };
const edgeTTS: TTS = { name: "edge-tts", synthesize: async (text) => Buffer.byteLength(text) * 10 };
const cloudTTS: TTS = { name: "cloud-tts", synthesize: async (text) => Buffer.byteLength(text) * 12 };

interface Turn {
  heard: string;
  reply: string;
  audioBytes: number;
}

async function sessionTurn(stt: STT, tts: TTS, audio: string): Promise<Turn> {
  // 세션 코드: 어떤 플러그인이 꽂혔는지 모르고 정해진 메서드만 부른다
  const heard = await stt.recognize(audio);
  const reply = heard.includes("예약") ? "네, 언제가 좋으세요?" : "다시 말씀해 주세요.";
  return { heard, reply, audioBytes: await tts.synthesize(reply) };
}

const a = await sessionTurn(localWhisperSTT, edgeTTS, "clip1");
const b = await sessionTurn(cloudSTT, cloudTTS, "clip1");
console.log("로컬 한 쌍:", JSON.stringify(a));
console.log("클라우드 쌍:", JSON.stringify(b));
check(a.heard === b.heard && a.reply === b.reply && a.audioBytes !== b.audioBytes, "플러그인을 바꿔도 대화 내용은 같고 공급자별 결과만 달라야 해요.");

worker.typescript:
// D29 · Part 4 · 작업자의 하루: 방이 생기면 비서가 출근해 일감(Job)을 처리한다 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_worker.ts
//   AgentServer에 entrypoint를 등록해 두면, 방이 열릴 때마다 서버가 일감을 만들어 entrypoint를 불러 준다(방마다 따로, 동시에)
//   (대체: @livekit/agents의 서버·JobContext 대신 같은 흐름의 미니 클래스)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface JobContext {
  room: string;
  state: string;
  log: string[];
}

type Entrypoint = (ctx: JobContext) => Promise<void>;

class AgentServer {
  entrypoint: Entrypoint | null = null;
  jobs: JobContext[] = [];
  register(fn: Entrypoint): void {
    // 이 함수를 '방에 들어갔을 때 할 일'로 등록
    this.entrypoint = fn;
  }
  async onRoomCreated(room: string): Promise<void> {
    const ctx: JobContext = { room, state: "assigned", log: [] }; // 방마다 일감 하나
    this.jobs.push(ctx);
    ctx.state = "running";
    await this.entrypoint?.(ctx);
    ctx.state = "done";
  }
}

const server = new AgentServer();
server.register(async (ctx) => {
  ctx.log.push(`${ctx.room}: connect`);
  await new Promise((r) => setTimeout(r, 10)); // 통화 중이라고 가정
  ctx.log.push(`${ctx.room}: 인사 · 통화 · 종료`);
});

await Promise.all([server.onRoomCreated("clinic-1"), server.onRoomCreated("clinic-2")]); // 두 방이 동시에
for (const j of server.jobs) console.log(j.room, j.state, JSON.stringify(j.log));
check(
