# D29 · Part 4~5 · 세 가지 연결: 브라우저 · 전화 · 서버 프로그램이 같은 비서에 붙는 길 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d29_connect.py   (LiveKit 서버 없이 · 인터넷·GPU·마이크 불필요)
#   참가자 종류(STANDARD · SIP · 프로그램)가 달라도 비서 코드는 같은 Room 이벤트만 본다. 달라지는 건 들어오는 길(전송 방식)뿐
#   (대체: 실제 WebRTC·SIP·WebSocket 연결 대신 길 이름과 코덱 표)
from dataclasses import dataclass


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


@dataclass
class Route:
    transport: str
    codec: str
    sample_rate: int


ROUTES = {
    "STANDARD": Route("WebRTC(브라우저 SDK)", "opus", 48000),
    "SIP": Route("전화망 → SIP Trunk → 방", "pcmu(G.711)", 8000),
    "PROGRAM": Route("서버 SDK(WebSocket 시그널링 + RTC)", "opus", 48000),
}


def agent_handles(participant_kind: str) -> str:
    """비서 코드: 참가자 종류를 구분하지 않고, 방에 들어온 오디오 트랙을 구독해서 답한다."""
    route = ROUTES[participant_kind]
    return f"track_subscribed({route.sample_rate}Hz) → STT → LLM → TTS → publish"


for kind, r in ROUTES.items():
    print(f"{kind:<9} {r.transport:<34} {r.codec:<12} {r.sample_rate}Hz")
handled = {k: agent_handles(k) for k in ROUTES}
same_flow = {h.split("Hz) → ", 1)[1] for h in handled.values()}
check(len(ROUTES) == 3 and same_flow == {"STT → LLM → TTS → publish"} and ROUTES["SIP"].sample_rate == 8000,
      "들어오는 길(코덱·샘플레이트)은 달라도 비서의 처리 흐름은 하나여야 해요.")

