function agentHandles(kind: string): string {
  // 비서 코드: 참가자 종류를 구분하지 않고, 방에 들어온 오디오 트랙을 구독해서 답한다
  return `track_subscribed(${ROUTES[kind].sampleRate}Hz) → STT → LLM → TTS → publish`;
}

for (const [kind, r] of Object.entries(ROUTES)) console.log(`${kind.padEnd(9)} ${r.transport.padEnd(34)} ${r.codec.padEnd(12)} ${r.sampleRate}Hz`);
