// D29 · Part 5 · 정리 퀴즈: LiveKit 핵심 다섯 문장을 작은 계산으로 확인 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d29_recap.ts
//   ① 토큰은 서버에서만 만든다(서명) ② 비서는 Worker가 방마다 보낸다 ③ 플러그인은 모양만 맞으면 교체 ④ 전화는 8 kHz ⑤ e2e 지연 식
//   (대체: 개념 퀴즈의 답을 코드로 계산)
import { createHmac } from "node:crypto";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const sign = (msg: string, secret: string): string => createHmac("sha256", secret).update(msg).digest("hex").slice(0, 12);

const payload = "room=clinic-1;sub=user-1";
const serverSig = sign(payload, "server-secret");
const quiz: Record<string, boolean | number> = {
  "서명 키를 아는 서버가 만든 출입증이 유효한가": sign(payload, "server-secret") === serverSig,
  "브라우저가 키 없이 만든 출입증이 유효한가": sign(payload, "guess") === serverSig,
  "방 3개에 필요한 일감 수": new Set(["a", "b", "c"]).size,
  "전화(8 kHz)의 20 ms 조각 샘플 수": Math.floor((8000 * 20) / 1000),
  "e2e(초) = 턴 0.5 + LLM 0.4 + TTS 0.2": Math.round((0.5 + 0.4 + 0.2) * 100) / 100,
};
for (const [q, a] of Object.entries(quiz)) console.log(`${q}: ${a}`);
check(Object.values(quiz).join() === "true,false,3,160,1.1", "서명 키가 없으면 출입증을 만들 수 없고, 전화 20 ms는 160샘플이에요.");
